//! Sounds (`spec/05-desktop-agent.md`, Hold cue and Alarm sounds).
//!
//! The alarm patterns and the drill chime are WAV files in `sounds/`
//! (CC0), generated by [`Clip::render`] (`s/sounds`) and built into the
//! app. A practice can replace one by putting a WAV file with the same name
//! in the `sounds` folder of the data directory; a file that cannot be read
//! falls back to the built-in sound, so a bad file never silences an alarm.
//!
//! The hold cue stays synthesised, because its pitch rises over the
//! configured hold time.
//!
//! One thread owns the output device, because a device stream is not `Send`
//! on every platform.

use std::f32::consts::TAU;
use std::io::Cursor;
use std::num::NonZero;
use std::path::{Path, PathBuf};
use std::sync::{Arc, mpsc};
use std::time::Duration;

use muster_core::io::AudioCmd;
use muster_proto::{CueMode, SoundPattern};
use rodio::{Player, Source};

const RATE: u32 = 48_000;
/// Replacement files larger than this are ignored.
const MAX_FILE_BYTES: u64 = 16 * 1024 * 1024;
/// Alarm volume: 50% of the setting, rising to 100% over 8 s.
const ALARM_RAMP: (f32, f32, f32) = (0.5, 1.0, 8.0);
/// `alarm_ramp` cue: 5% rising to 40% over the hold.
const CUE_RAMP: (f32, f32) = (0.05, 0.4);

/// One tone segment of an alarm pattern: frequency in Hz (0 = silence) and
/// length in ms.
fn pattern(p: SoundPattern) -> &'static [(f32, u32)] {
    match p {
        // B: three quick high beeps, then a pause.
        SoundPattern::B => &[
            (1000.0, 120),
            (0.0, 80),
            (1000.0, 120),
            (0.0, 80),
            (1000.0, 120),
            (0.0, 700),
        ],
        // C: a slow two-note call, low then high.
        SoundPattern::C => &[(520.0, 450), (740.0, 450), (0.0, 500)],
        // A (default): 880 and 660 Hz, 200 ms each, three times, then
        // 600 ms of silence.
        _ => &[
            (880.0, 200),
            (660.0, 200),
            (880.0, 200),
            (660.0, 200),
            (880.0, 200),
            (660.0, 200),
            (0.0, 600),
        ],
    }
}

/// What the synthesiser makes.
#[derive(Debug, Clone, Copy)]
enum Sound {
    /// The soft hold cue: 500 Hz rising to 800 Hz over the hold, with a
    /// 4 Hz pulse, -30 dBFS rising to -20 dBFS.
    Cue { hold_ms: u32 },
    /// One cycle of an alarm pattern at full level.
    Cycle(SoundPattern),
    /// The 2 s drill chime.
    Chime,
}

/// A mono synthesiser.
#[derive(Debug)]
struct Synth {
    sound: Sound,
    n: u64,
    phase: f32,
    len: u64,
}

impl Synth {
    fn new(sound: Sound) -> Self {
        let ms = match sound {
            Sound::Cue { hold_ms } => hold_ms,
            Sound::Cycle(p) => pattern(p).iter().map(|s| s.1).sum(),
            Sound::Chime => 2000,
        };
        Synth {
            sound,
            n: 0,
            phase: 0.0,
            len: u64::from(ms) * u64::from(RATE) / 1000,
        }
    }
}

impl Iterator for Synth {
    type Item = f32;

    fn next(&mut self) -> Option<f32> {
        if self.n >= self.len {
            return None;
        }
        let t = self.n as f32 / RATE as f32;
        let t_ms = t * 1000.0;
        self.n += 1;
        let (freq, amp) = match self.sound {
            Sound::Cue { hold_ms } => {
                let x = (t_ms / hold_ms.max(1) as f32).min(1.0);
                let level = 10f32.powf((-30.0 + 10.0 * x) / 20.0);
                let pulse = 0.8 + 0.2 * (TAU * 4.0 * t).sin();
                let fade = (t_ms / 10.0).min(1.0);
                (500.0 + 300.0 * x, level * pulse * fade)
            }
            Sound::Cycle(p) => {
                let mut rest = t_ms;
                let mut out = (0.0, 0.0);
                for (f, d) in pattern(p) {
                    let d = *d as f32;
                    if rest < d {
                        // 5 ms ramps at both ends of each tone.
                        let ramp = (rest / 5.0).min((d - rest) / 5.0).clamp(0.0, 1.0);
                        out = (*f, if *f > 0.0 { 0.6 * ramp } else { 0.0 });
                        break;
                    }
                    rest -= d;
                }
                out
            }
            Sound::Chime => {
                let decay = (-t * 2.5).exp();
                let f = if t < 0.4 { 660.0 } else { 990.0 };
                (f, 0.25 * decay * (t_ms / 5.0).min(1.0))
            }
        };
        self.phase = (self.phase + TAU * freq / RATE as f32) % TAU;
        Some(amp * self.phase.sin())
    }
}

/// A sound shipped as a replaceable WAV file.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Clip {
    AlarmA,
    AlarmB,
    AlarmC,
    Chime,
}

impl Clip {
    pub const ALL: [Clip; 4] = [Clip::AlarmA, Clip::AlarmB, Clip::AlarmC, Clip::Chime];

    pub fn file_name(self) -> &'static str {
        match self {
            Clip::AlarmA => "alarm-a.wav",
            Clip::AlarmB => "alarm-b.wav",
            Clip::AlarmC => "alarm-c.wav",
            Clip::Chime => "drill-chime.wav",
        }
    }

    fn alarm(p: SoundPattern) -> Clip {
        match p {
            SoundPattern::B => Clip::AlarmB,
            SoundPattern::C => Clip::AlarmC,
            _ => Clip::AlarmA,
        }
    }

    /// The built-in file.
    pub fn builtin(self) -> &'static [u8] {
        match self {
            Clip::AlarmA => include_bytes!("../../../../sounds/alarm-a.wav"),
            Clip::AlarmB => include_bytes!("../../../../sounds/alarm-b.wav"),
            Clip::AlarmC => include_bytes!("../../../../sounds/alarm-c.wav"),
            Clip::Chime => include_bytes!("../../../../sounds/drill-chime.wav"),
        }
    }

    /// The samples the built-in file is generated from (48 kHz mono). An
    /// alarm clip is one cycle; the app loops it.
    pub fn render(self) -> Vec<f32> {
        let s = match self {
            Clip::AlarmA => Sound::Cycle(SoundPattern::A),
            Clip::AlarmB => Sound::Cycle(SoundPattern::B),
            Clip::AlarmC => Sound::Cycle(SoundPattern::C),
            Clip::Chime => Sound::Chime,
        };
        Synth::new(s).collect()
    }
}

/// 16-bit PCM mono WAV at 48 kHz.
pub fn wav_bytes(samples: &[f32]) -> Vec<u8> {
    let data_len = (samples.len() * 2) as u32;
    let mut b = Vec::with_capacity(44 + data_len as usize);
    b.extend_from_slice(b"RIFF");
    b.extend_from_slice(&(36 + data_len).to_le_bytes());
    b.extend_from_slice(b"WAVEfmt ");
    b.extend_from_slice(&16u32.to_le_bytes());
    b.extend_from_slice(&1u16.to_le_bytes()); // PCM
    b.extend_from_slice(&1u16.to_le_bytes()); // mono
    b.extend_from_slice(&RATE.to_le_bytes());
    b.extend_from_slice(&(RATE * 2).to_le_bytes());
    b.extend_from_slice(&2u16.to_le_bytes());
    b.extend_from_slice(&16u16.to_le_bytes());
    b.extend_from_slice(b"data");
    b.extend_from_slice(&data_len.to_le_bytes());
    for s in samples {
        let v = (s.clamp(-1.0, 1.0) * f32::from(i16::MAX)).round() as i16;
        b.extend_from_slice(&v.to_le_bytes());
    }
    b
}

/// Decoded audio, shared between plays.
#[derive(Debug, Clone)]
struct Pcm {
    samples: Arc<[f32]>,
    channels: NonZero<u16>,
    rate: NonZero<u32>,
}

fn decode(bytes: Vec<u8>) -> Option<Pcm> {
    let d = rodio::Decoder::new_wav(Cursor::new(bytes)).ok()?;
    let (channels, rate) = (d.channels(), d.sample_rate());
    let samples: Arc<[f32]> = d.collect();
    (!samples.is_empty()).then_some(Pcm {
        samples,
        channels,
        rate,
    })
}

/// The clip: the replacement in `dir` if there is a readable one, else the
/// built-in file.
fn load(clip: Clip, dir: Option<&Path>) -> Pcm {
    if let Some(d) = dir {
        let p = d.join(clip.file_name());
        if let Ok(meta) = std::fs::metadata(&p) {
            let replaced = if meta.len() > MAX_FILE_BYTES {
                None
            } else {
                std::fs::read(&p).ok().and_then(decode)
            };
            match replaced {
                Some(pcm) => return pcm,
                None => tracing::warn!(
                    "{} is not a readable WAV file of at most 16 MB; using the built-in sound",
                    p.display()
                ),
            }
        }
    }
    decode(clip.builtin().to_vec()).unwrap_or_else(|| Pcm {
        // Unreachable with the shipped files; a test checks they decode.
        samples: clip.render().into(),
        channels: NonZero::<u16>::MIN,
        rate: NonZero::new(RATE).unwrap_or(NonZero::<u32>::MIN),
    })
}

/// Plays a [`Pcm`], optionally looping, with a linear volume ramp.
#[derive(Debug)]
struct Play {
    pcm: Pcm,
    pos: usize,
    n: u64,
    looping: bool,
    /// Gain from, gain to, over this many samples (all channels).
    ramp: (f32, f32, u64),
    /// Stop after this many samples (all channels), if set.
    limit: Option<u64>,
}

impl Play {
    fn new(pcm: Pcm, looping: bool, from: f32, to: f32, ramp_s: f32) -> Self {
        let per_s = f64::from(pcm.rate.get()) * f64::from(pcm.channels.get());
        Play {
            pcm,
            pos: 0,
            n: 0,
            looping,
            ramp: (from, to, (f64::from(ramp_s) * per_s) as u64),
            limit: None,
        }
    }

    fn limit_ms(mut self, ms: u32) -> Self {
        let per_ms = f64::from(self.pcm.rate.get()) * f64::from(self.pcm.channels.get()) / 1000.0;
        self.limit = Some((f64::from(ms) * per_ms) as u64);
        self
    }
}

impl Iterator for Play {
    type Item = f32;

    fn next(&mut self) -> Option<f32> {
        if self.limit.is_some_and(|l| self.n >= l) {
            return None;
        }
        if self.pos >= self.pcm.samples.len() {
            if !self.looping {
                return None;
            }
            self.pos = 0;
        }
        let (from, to, over) = self.ramp;
        let x = if over == 0 {
            1.0
        } else {
            (self.n as f32 / over as f32).min(1.0)
        };
        let s = self.pcm.samples[self.pos] * (from + (to - from) * x);
        self.pos += 1;
        self.n += 1;
        Some(s)
    }
}

impl Source for Play {
    fn current_span_len(&self) -> Option<usize> {
        None
    }

    fn channels(&self) -> rodio::ChannelCount {
        self.pcm.channels
    }

    fn sample_rate(&self) -> rodio::SampleRate {
        self.pcm.rate
    }

    fn total_duration(&self) -> Option<Duration> {
        None
    }
}

impl Source for Synth {
    fn current_span_len(&self) -> Option<usize> {
        None
    }

    fn channels(&self) -> rodio::ChannelCount {
        NonZero::<u16>::MIN
    }

    fn sample_rate(&self) -> rodio::SampleRate {
        NonZero::new(RATE).unwrap_or(NonZero::<u32>::MIN)
    }

    fn total_duration(&self) -> Option<Duration> {
        Some(Duration::from_millis(self.len * 1000 / u64::from(RATE)))
    }
}

/// Commands to the audio thread.
#[derive(Debug, Clone, Copy)]
pub enum Cmd {
    Agent(AudioCmd),
    Test(SoundPattern),
}

/// Handle to the audio thread.
#[derive(Debug, Clone)]
pub struct Audio {
    tx: mpsc::Sender<Cmd>,
}

impl Audio {
    /// Starts the audio thread, with replacement sounds read from
    /// `sounds_dir` at each play. Returns the handle and whether an output
    /// device opened (reported to the agent as audio status).
    pub fn start(sounds_dir: PathBuf) -> (Audio, bool) {
        let (tx, rx) = mpsc::channel::<Cmd>();
        let (ok_tx, ok_rx) = mpsc::channel::<bool>();
        let spawned = std::thread::Builder::new()
            .name("muster-audio".into())
            .spawn(move || run(rx, ok_tx, sounds_dir));
        let ok = spawned.is_ok() && ok_rx.recv().unwrap_or(false);
        (Audio { tx }, ok)
    }

    pub fn send(&self, c: Cmd) {
        let _ = self.tx.send(c);
    }
}

fn run(rx: mpsc::Receiver<Cmd>, ok: mpsc::Sender<bool>, dir: PathBuf) {
    let mut sink = match rodio::DeviceSinkBuilder::open_default_sink() {
        Ok(s) => s,
        Err(e) => {
            tracing::warn!("no audio output: {e}");
            let _ = ok.send(false);
            // Keep draining so senders never block.
            while rx.recv().is_ok() {}
            return;
        }
    };
    sink.log_on_drop(false);
    let _ = ok.send(true);
    let cue = Player::connect_new(sink.mixer());
    let alarm = Player::connect_new(sink.mixer());
    let other = Player::connect_new(sink.mixer());
    let dir = Some(dir.as_path());
    fn start<S: Source + Send + 'static>(p: &Player, s: S) {
        p.clear();
        p.append(s);
        p.play();
    }
    while let Ok(c) = rx.recv() {
        match c {
            Cmd::Agent(AudioCmd::StartCue { mode, hold_ms }) => match mode {
                CueMode::Silent => {}
                CueMode::AlarmRamp => {
                    let pcm = load(Clip::AlarmA, dir);
                    let secs = hold_ms as f32 / 1000.0;
                    let s = Play::new(pcm, true, CUE_RAMP.0, CUE_RAMP.1, secs).limit_ms(hold_ms);
                    start(&cue, s);
                }
                _ => start(&cue, Synth::new(Sound::Cue { hold_ms })),
            },
            Cmd::Agent(AudioCmd::StopCue) => cue.clear(),
            Cmd::Agent(AudioCmd::StartAlarm { pattern }) => {
                let pcm = load(Clip::alarm(pattern), dir);
                let (from, to, secs) = ALARM_RAMP;
                start(&alarm, Play::new(pcm, true, from, to, secs));
            }
            Cmd::Agent(AudioCmd::StopAlarm) => alarm.clear(),
            Cmd::Agent(AudioCmd::Chime) => {
                start(
                    &other,
                    Play::new(load(Clip::Chime, dir), false, 0.5, 0.5, 0.0),
                );
            }
            Cmd::Test(p) => {
                let s = Play::new(load(Clip::alarm(p), dir), true, 0.5, 0.5, 0.0).limit_ms(3000);
                start(&other, s);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn samples_of(b: &[u8]) -> Vec<i16> {
        b[44..]
            .as_chunks::<2>()
            .0
            .iter()
            .map(|c| i16::from_le_bytes(*c))
            .collect()
    }

    #[test]
    fn built_in_files_match_the_generator() {
        // Regenerate with s/sounds if this fails after changing the
        // synthesiser. Allow a little difference for platform maths.
        for c in Clip::ALL {
            let want = samples_of(&wav_bytes(&c.render()));
            let got = samples_of(c.builtin());
            assert_eq!(want.len(), got.len(), "{}", c.file_name());
            let worst = want
                .iter()
                .zip(&got)
                .map(|(a, b)| (i32::from(*a) - i32::from(*b)).abs())
                .max()
                .unwrap_or(0);
            assert!(worst <= 2, "{} differs by {worst}", c.file_name());
        }
    }

    #[test]
    fn built_in_files_decode() {
        for c in Clip::ALL {
            let p = decode(c.builtin().to_vec()).expect("decodes");
            assert_eq!(p.channels.get(), 1);
            assert_eq!(p.rate.get(), RATE);
        }
    }

    #[test]
    fn a_bad_replacement_falls_back_to_the_built_in_sound() {
        let d = tempfile::tempdir().expect("tempdir");
        std::fs::write(d.path().join("alarm-a.wav"), b"not a wav").expect("write");
        let p = load(Clip::AlarmA, Some(d.path()));
        assert_eq!(p.samples.len(), Clip::AlarmA.render().len());
        // A valid replacement is used.
        std::fs::write(d.path().join("alarm-a.wav"), wav_bytes(&[0.1; 4800])).expect("write");
        assert_eq!(load(Clip::AlarmA, Some(d.path())).samples.len(), 4800);
    }

    #[test]
    fn alarm_loops_and_ramps_up() {
        let pcm = load(Clip::AlarmA, None);
        let mut p = Play::new(pcm, true, 0.5, 1.0, 8.0);
        let peak = |p: &mut Play| {
            (0..RATE)
                .filter_map(|_| p.next())
                .fold(0.0f32, |m, x| m.max(x.abs()))
        };
        let early = peak(&mut p);
        for _ in 0..8 * RATE {
            p.next();
        }
        let late = peak(&mut p);
        assert!(late > early * 1.5, "{late} > {early}");
        assert!(p.next().is_some(), "loops until stopped");
    }

    #[test]
    fn cue_is_quiet_and_ends_with_the_hold() {
        let s: Vec<f32> = Synth::new(Sound::Cue { hold_ms: 1500 }).collect();
        assert_eq!(s.len() as u64, 1500 * u64::from(RATE) / 1000);
        // Never above -20 dBFS.
        assert!(s.iter().all(|x| x.abs() <= 0.101));
    }

    #[test]
    fn patterns_differ() {
        assert_ne!(pattern(SoundPattern::A), pattern(SoundPattern::B));
        assert_ne!(pattern(SoundPattern::B), pattern(SoundPattern::C));
    }
}
